import React, { useState, useEffect } from 'react'
import { Sparkles, FileText, Plus, Copy, Trash2, ArrowUpRight } from 'lucide-react'
import { Button, Alert, Input } from '../../../components/common'
import { careerAgentAPI } from '../../../services/careerAgentAPI'
import { resumeAPI } from '../../../services/api'

const ROLE_TEMPLATES = [
  { role: 'AI/ML Engineer', focus: 'Machine learning, deep learning, model deployment, Python, research' },
  { role: 'Full Stack Developer', focus: 'React, Node.js, MongoDB, REST APIs, system design' },
  { role: 'Data Analyst', focus: 'SQL, Power BI, Tableau, Excel, data storytelling' },
  { role: 'Data Scientist', focus: 'Statistics, Python, ML algorithms, experimentation, visualization' },
  { role: 'Backend Developer', focus: 'Node.js, Express, databases, API design, system scalability' },
  { role: 'Frontend Developer', focus: 'React, JavaScript, CSS, accessibility, performance' },
  { role: 'DevOps Engineer', focus: 'Docker, CI/CD, AWS, Linux, infrastructure as code' },
  { role: 'Cybersecurity Analyst', focus: 'Network security, threat analysis, Python scripting, compliance' },
]

export const MultipleResumes = () => {
  const [resumes, setResumes] = useState([])
  const [generating, setGenerating] = useState(null) // track which role is generating
  const [loadingList, setLoadingList] = useState(true)
  const [error, setError] = useState('')
  const [message, setMessage] = useState('')
  const [customRole, setCustomRole] = useState('')

  useEffect(() => {
    resumeAPI.list()
      .then((res) => setResumes(res?.data?.items || []))
      .catch(() => {})
      .finally(() => setLoadingList(false))
  }, [])

  const generate = async (targetRole) => {
    const role = targetRole || customRole.trim()
    if (!role) return
    setGenerating(role)
    setError('')
    setMessage('')
    try {
      const res = await careerAgentAPI.generateATSResume(role)
      if (res?.success) {
        setResumes((prev) => [res.data.resume, ...prev])
        setMessage(`✓ "${role}" resume created and saved. Review it in the Resume Editor before using.`)
      } else {
        setError('Generation failed. Complete your career profile first.')
      }
    } catch (err) {
      setError(err?.message || 'Resume generation unavailable.')
    } finally {
      setGenerating(null)
    }
  }

  const remove = async (id) => {
    try {
      await resumeAPI.remove(id)
      setResumes((prev) => prev.filter((r) => r._id !== id))
    } catch {
      setError('Could not delete resume.')
    }
  }

  return (
    <div className="career-section">
      <div className="career-section-header">
        <span className="section-label">MULTIPLE RESUME VERSIONS</span>
        <h2>One master profile → multiple targeted resumes</h2>
        <p className="career-muted">
          Each resume is generated from your verified profile data with emphasis and keywords adjusted for the target role.
          No qualifications are invented — only emphasis and ordering change.
        </p>
      </div>

      {/* Role chips */}
      <div className="multi-resume-generator">
        <span className="section-label">GENERATE FOR A ROLE</span>
        <div className="role-chips">
          {ROLE_TEMPLATES.map(({ role }) => (
            <button
              key={role}
              className={`role-chip ${generating === role ? 'active' : ''}`}
              onClick={() => generate(role)}
              disabled={!!generating}
            >
              {generating === role ? <Sparkles size={12} /> : <Plus size={12} />} {role}
            </button>
          ))}
        </div>
        <div className="multi-resume-custom">
          <Input
            label="Or generate for a custom role"
            value={customRole}
            onChange={(e) => setCustomRole(e.target.value)}
            placeholder="e.g. Embedded Systems Engineer"
          />
          <Button variant="outline" onClick={() => generate()} disabled={!customRole.trim() || !!generating} loading={generating === customRole}>
            <Sparkles size={14} /> Generate
          </Button>
        </div>
      </div>

      {message && <Alert type="success" message={message} />}
      {error && <Alert type="error" message={error} />}

      {/* Resume list */}
      <div className="multi-resume-list">
        <span className="section-label">YOUR RESUME VERSIONS ({resumes.length})</span>
        {loadingList && <p className="career-muted">Loading your resumes…</p>}
        {!loadingList && resumes.length === 0 && (
          <p className="career-muted">No resumes yet. Generate one above or visit the Resume Editor.</p>
        )}
        {resumes.map((r) => (
          <div key={r._id} className="multi-resume-card">
            <div className="multi-resume-card-info">
              <FileText size={18} color="#6655ee" />
              <div>
                <strong>{r.title}</strong>
                <small>{r.template || 'ats-modern'} · v{r.version || 1} · {r.aiGenerated ? 'AI-generated' : 'Manual'}</small>
              </div>
            </div>
            <div className="multi-resume-card-actions">
              {r.analysis?.score != null && (
                <span className="resume-score-badge">{r.analysis.score}% ATS</span>
              )}
              <a href="/resume" className="multi-resume-edit-link">
                Edit <ArrowUpRight size={13} />
              </a>
              <button className="multi-resume-delete" onClick={() => remove(r._id)} title="Delete this resume version">
                <Trash2 size={14} />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}
