import React from 'react'
import { CheckCircle2, Circle, FileText, XCircle } from 'lucide-react'
import { Badge, Button } from './common'
import { documentAPI } from '../services/api'

const statusLabels = {
  applied: 'Application submitted',
  under_review: 'Under review',
  shortlisted: 'Shortlisted',
  assessment: 'Assessment',
  interview: 'Interview',
  selected: 'Selected',
  rejected: 'Not selected',
  withdrawn: 'Withdrawn',
}

const badgeVariant = (status) => status === 'selected' ? 'green' : status === 'rejected' ? 'red' : status === 'withdrawn' ? 'gray' : 'yellow'

export const ApplicationTracker = ({ applications, loading, error }) => {
  const downloadResume = async (applicationId, fileName) => {
    const response = await documentAPI.downloadApplicationResume(applicationId)
    const url = URL.createObjectURL(response)
    const link = document.createElement('a')
    link.href = url
    link.download = fileName || 'resume'
    link.click()
    URL.revokeObjectURL(url)
  }

  if (loading) return <div className="workspace-empty">Loading applications...</div>
  if (error) return <div className="workspace-error">{error}</div>
  if (!applications.length) return <div className="workspace-empty">You have not applied to any opportunities yet.</div>

  return <div className="application-tracker-list">{applications.map((application) => {
    const opportunity = application.opportunityId || {}
    const history = application.statusHistory || []
    return <article className="application-tracker-card" key={application._id}>
      <div className="application-tracker-head">
        <div><span className="section-label">{opportunity.type || 'Opportunity'}</span><h2>{opportunity.title || 'Opportunity application'}</h2><p>{opportunity.location || 'Industry opportunity'} · Applied {new Date(application.createdAt).toLocaleDateString()}</p></div>
        <Badge variant={badgeVariant(application.status)}>{statusLabels[application.status] || application.status}</Badge>
      </div>
      {application.status === 'selected' && <div className="tracker-callout success"><CheckCircle2 size={18} /> Congratulations. You have been selected for this opportunity.</div>}
      {application.status === 'rejected' && <div className="tracker-callout danger"><XCircle size={18} /><div><strong>Application not selected</strong><p>{application.feedback || 'The industry has not provided additional feedback.'}</p></div></div>}
      <div className="application-timeline">{history.map((event, index) => <div className="timeline-event" key={`${event.status}-${event.changedAt}-${index}`}><span className="timeline-dot"><Circle size={12} fill="currentColor" /></span><div><strong>{statusLabels[event.status] || event.status}</strong><small>{new Date(event.changedAt).toLocaleString()}</small>{event.note && <p>{event.note}</p>}</div></div>)}</div>
      <div className="application-tracker-foot"><span>Submitted as: {application.applicant?.name || 'Your profile'} · {application.applicant?.email || ''} · Resume v{application.resumeVersion || 1}</span>{application.resume && <Button size="sm" variant="outline" onClick={() => downloadResume(application._id, application.resume.originalName)}><FileText size={14} /> View submitted resume</Button>}</div>
    </article>
  })}</div>
}
