const roleMenus = {
  student: [
    [
      "STUDENT WORKSPACE",
      [
        ["AI Career Agent", ROUTES.CAREER_AGENT, Sparkles],
        ["Opportunities", ROUTES.OPPORTUNITIES, Compass],
        ["Resume Maker", "/resume", FileText],
        ["Application Tracker", ROUTES.APPLICATIONS, ClipboardCheck],
      ],
    ],
  ],
  industry: [
    ["ACCOUNT", [["Profile", ROUTES.PROFILE, User]]],
    [
      "RECRUIT",
      [
        ["My postings", "/manage-opportunities", Briefcase],
        ["Applicants", "/applicants", Users],
      ],
    ],
  ],
  academician: [
    ["ACCOUNT", [["Profile", ROUTES.PROFILE, User]]],
    [
      "ACADEMIC-INDUSTRY",
      [
        ["Find collaborations", "/academic-opportunities", Network],
        ["My postings", "/academic-opportunities", BookOpen],
      ],
    ],
  ],
  institution: [
    ["ACCOUNT", [["Profile", ROUTES.PROFILE, User]]],
    ["INSTITUTION", [["Analytics dashboard", ROUTES.DASHBOARD, BarChart3]]],
  ],
};

export const WorkspaceShell = ({ user, onLogout, children }) => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const location = useLocation();
  const pathname = location.pathname;
  const searchParams = new URLSearchParams(location.search);
  const currentTabParam = searchParams.get("tab") || "dashboard";

  const isCareerAgentRoute = pathname === ROUTES.CAREER_AGENT;
  const [careerSubmenuOpen, setCareerSubmenuOpen] = useState(true);

  useEffect(() => {
    if (isCareerAgentRoute) {
      setCareerSubmenuOpen(true);
    }
  }, [isCareerAgentRoute]);

  const menus = roleMenus[user?.role] || roleMenus.student;

  return (
    <div className="workspace-shell">
      <aside className={`workspace-sidebar ${sidebarOpen ? "is-open" : ""}`}>
        <div className="sidebar-brand">
          <Link to={ROUTES.HOME} className="brand">
            <AICPLogo compact showBadge />
          </Link>
          <button
            className="sidebar-close"
            onClick={() => setSidebarOpen(false)}
            aria-label="Close sidebar"
          >
            <X size={19} />
          </button>
        </div>
        <div className="sidebar-role">
          <span className="sidebar-role-icon">
            <User size={17} />
          </span>
          <span>
            <strong>{user?.name || "AICP member"}</strong>
            <small>{user?.role || "member"}</small>
          </span>
          <ChevronDown size={14} />
        </div>
        <nav className="workspace-nav">
          <Link
            to={ROUTES.DASHBOARD}
            className={`workspace-nav-home ${pathname === ROUTES.DASHBOARD ? "is-active" : ""}`}
            onClick={() => setSidebarOpen(false)}
          >
            <LayoutDashboard size={16} /> Dashboard
          </Link>
          {menus.map(([section, links]) => (
            <div className="nav-section" key={section}>
              <span>{section}</span>
              {links.map(([label, to, Icon]) => {
                const isCareerAgent = to === ROUTES.CAREER_AGENT;

                if (isCareerAgent && user?.role === "student") {
                  return (
                    <div key={`${section}-${label}`} className="sidebar-group">
                      <div
                        className={`workspace-nav-parent ${
                          isCareerAgentRoute ? "is-active" : ""
                        }`}
                      >
                        <Link
                          to={ROUTES.CAREER_AGENT}
                          className="workspace-nav-link-main"
                          onClick={() => {
                            setCareerSubmenuOpen(true);
                            setSidebarOpen(false);
                          }}
                        >
                          <Icon size={15} /> <span>{label}</span>
                        </Link>
                        <button
                          type="button"
                          className="nav-chevron-toggle"
                          onClick={(e) => {
                            e.preventDefault();
                            e.stopPropagation();
                            setCareerSubmenuOpen(!careerSubmenuOpen);
                          }}
                          aria-label="Toggle AI Career Agent modules"
                          title="Toggle modules"
                        >
                          <ChevronDown
                            className={`nav-chevron ${
                              careerSubmenuOpen ? "rotated" : ""
                            }`}
                            size={14}
                          />
                        </button>
                      </div>

                      {careerSubmenuOpen && (
                        <div className="sidebar-subnav">
                          {CAREER_TABS.map((tab) => {
                            const TabIcon = tab.icon;
                            const isSubActive =
                              isCareerAgentRoute &&
                              currentTabParam === tab.id;
                            return (
                              <Link
                                key={tab.id}
                                to={`/career-agent?tab=${tab.id}`}
                                className={`sidebar-subnav-item ${
                                  isSubActive ? "is-active" : ""
                                }`}
                                onClick={() => setSidebarOpen(false)}
                              >
                                <TabIcon size={13} />
                                <span>{tab.label}</span>
                              </Link>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  );
                }

                return (
                  <Link
                    to={to}
                    key={`${section}-${label}`}
                    className={pathname === to ? "is-active" : ""}
                    onClick={() => setSidebarOpen(false)}
                  >
                    <Icon size={15} /> {label}
                    <ChevronDown className="nav-chevron" size={12} />
                  </Link>
                );
              })}
            </div>
          ))}
        </nav>
        {user?.role !== "student" && (
          <div className="sidebar-completion">
            <div className="completion-icon">
              <Sparkles size={16} />
            </div>
            <strong>Complete your profile</strong>
            <p>Add skills and interests to get better recommendations.</p>
            <div className="completion-bar">
              <span />
            </div>
            <small>75%</small>
            <Link to={ROUTES.PROFILE}>
              Update profile <ArrowUpRight size={13} />
            </Link>
          </div>
        )}
        <button className="sidebar-signout" onClick={onLogout}>
          <LogOut size={16} />
          <span>Sign out</span>
        </button>
      </aside>
      <div className="workspace-main">
        <header className="workspace-header">
          <button
            className="sidebar-trigger"
            onClick={() => setSidebarOpen(true)}
            aria-label="Open sidebar"
          >
            <Menu size={20} />
          </button>
          <div className="workspace-search">
            <Search size={16} />
            <input
              placeholder={
                user?.role === "industry"
                  ? "Search students, skills, roles, programs..."
                  : "Search AI tools, resumes, applications..."
              }
            />
          </div>
          <div className="workspace-header-actions">
            <button aria-label="Notifications" title="Notifications">
              <Bell size={18} />
              <i />
            </button>
            <button aria-label="Messages" title="Messages">
              <Users size={17} />
            </button>
            <div className="header-user">
              <span className="header-avatar">
                <User size={16} />
              </span>
              <span>
                <strong>{user?.name || "Member"}</strong>
                <small>{user?.role || "AICP"}</small>
              </span>
            </div>
            <button 
              className="header-signout-btn" 
              onClick={onLogout} 
              title="Sign out of your account"
            >
              <LogOut size={16} />
              <span>Sign out</span>
            </button>
          </div>
        </header>
        <main className="workspace-content">{children}</main>
      </div>
    </div>
  );
};

const SparklesIcon = () => <span className="completion-spark">✦</span>;
