import React, { useEffect, useState } from 'react'
import { Copy, Download, FileText, Plus, Save, Sparkles, Upload } from 'lucide-react'
import { Alert, Button, Input } from '../../components/common'
import { aiAPI, resumeAPI } from '../../services/api'

const emptyResume = { title: 'General Resume', template: 'ats-modern', personal: { name: '', email: '', phone: '', location: '', linkedin: '', github: '', portfolio: '' }, summary: '', skills: [], education: [], experience: [], projects: [], certifications: [], achievements: [], publications: [], languages: [], customSections: [] }
const textToItems = (text, key = 'description') => text.split(/\r?\n/).map((value) => value.trim()).filter(Boolean).map((value) => ({ [key]: value }))
const itemsToText = (items = [], key = 'description') => items.map((item) => item[key] || item.title || '').filter(Boolean).join('\n')
const ResumeSection = ({ title, value, fallback }) => <section className="resume-section"><h4>{title}</h4><p>{value || fallback}</p></section>

export const ResumeBuilder = () => {
  const [resume, setResume] = useState(emptyResume)
  const [analysis, setAnalysis] = useState(null)
  const [assistantText, setAssistantText] = useState('')
  const [assistantResult, setAssistantResult] = useState(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [message, setMessage] = useState('')
  const update = (field, value) => setResume((current) => ({ ...current, [field]: value }))
  const updatePersonal = (field, value) => setResume((current) => ({ ...current, personal: { ...current.personal, [field]: value } }))

  useEffect(() => { resumeAPI.list().then((response) => { const item = response?.data?.items?.[0]; if (item) setResume(item) }).catch(() => {}).finally(() => setLoading(false)) }, [])
  const createFromProfile = async () => { setSaving(true); try { const response = await resumeAPI.createFromProfile({ title: 'Profile Resume' }); setResume(response.data.resume); setMessage('Resume created from verified profile data.') } catch (error) { setMessage(error?.message || 'Profile import failed.') } finally { setSaving(false) } }
  const createBlank = async () => { setSaving(true); try { const response = await resumeAPI.create({ title: 'New Resume' }); setResume(response.data.resume); setMessage('Blank structured resume created.') } catch (error) { setMessage(error?.message || 'Resume creation failed.') } finally { setSaving(false) } }
  const upload = async (event) => { const file = event.target.files?.[0]; if (!file) return; setSaving(true); try { const response = await resumeAPI.upload(file, file.name); setResume(response.data.resume); setAnalysis(response.data.analysis); setMessage('Resume uploaded and analyzed. Review extracted fields before using them.') } catch (error) { setMessage(error?.message || 'Resume upload failed.') } finally { setSaving(false) } }
  const save = async () => { if (!resume._id) return createBlank(); setSaving(true); try { const response = await resumeAPI.update(resume._id, resume); setResume(response.data.resume); setMessage('Resume saved.') } catch (error) { setMessage(error?.message || 'Resume could not be saved.') } finally { setSaving(false) } }
  const duplicate = async () => { if (!resume._id) return; try { const response = await resumeAPI.duplicate(resume._id, { title: `${resume.title} version` }); setResume(response.data.resume); setMessage('New resume version created without changing the original.') } catch (error) { setMessage(error?.message || 'Could not duplicate resume.') } }
  const analyze = async () => { if (!resume._id) return setMessage('Save the resume before analyzing it.'); setSaving(true); try { const response = await resumeAPI.analyze(resume._id); setResume(response.data.resume); setAnalysis(response.data.analysis); setMessage(response.message || 'Resume analysis complete.') } catch (error) { setMessage(error?.message || 'AI unavailable. Continue editing manually.') } finally { setSaving(false) } }
  const askAssistant = async () => { if (!assistantText.trim()) return; setSaving(true); try { const response = await aiAPI.resumeOperation({ operation: 'chat', message: assistantText, text: assistantText, resume, facts: resume }); setAssistantResult(response?.data?.result || null) } catch (error) { setMessage(error?.message || 'AI Assistant temporarily unavailable.') } finally { setSaving(false) } }

  if (loading) return <div className="workspace-empty">Loading your resume workspace...</div>
  return <div className="resume-builder">
    <div className="resume-builder-heading"><div><span className="section-label">AICP RESUME INTELLIGENCE ENGINE</span><h1>Build a truthful resume that moves with your work.</h1><p>Your profile is the source of verified facts. AI suggestions remain reviewable and never silently overwrite your content.</p></div><div className="resume-builder-actions"><Button variant="nav" onClick={save} loading={saving}><Save size={16} /> Save</Button><Button variant="outline" onClick={() => window.print()}><Download size={16} /> Export PDF</Button></div></div>
    {message && <Alert type="info" message={message} />}
    <div className="resume-mode-bar"><Button variant="outline" onClick={createFromProfile}><Sparkles size={15} /> Build from profile</Button><label className="resume-upload-button"><Upload size={15} /> Upload PDF/DOCX<input type="file" accept=".pdf,.docx,.doc" onChange={upload} /></label><Button variant="outline" onClick={createBlank}><Plus size={15} /> Start from scratch</Button>{resume._id && <Button variant="outline" onClick={duplicate}><Copy size={15} /> Duplicate version</Button>}</div>
    <div className="resume-builder-grid">
      <form className="resume-form" onSubmit={(event) => { event.preventDefault(); save() }}><div className="resume-form-title"><FileText size={18} /><strong>Structured resume editor</strong></div><Input label="Resume name" value={resume.title || ''} onChange={(event) => update('title', event.target.value)} placeholder="Frontend Developer Resume" /><div className="profile-form-grid"><Input label="Full name" value={resume.personal?.name || ''} onChange={(event) => updatePersonal('name', event.target.value)} /><Input label="Email" value={resume.personal?.email || ''} onChange={(event) => updatePersonal('email', event.target.value)} /></div><div className="profile-form-grid"><Input label="Phone" value={resume.personal?.phone || ''} onChange={(event) => updatePersonal('phone', event.target.value)} /><Input label="Location" value={resume.personal?.location || ''} onChange={(event) => updatePersonal('location', event.target.value)} /></div><Input label="LinkedIn" value={resume.personal?.linkedin || ''} onChange={(event) => updatePersonal('linkedin', event.target.value)} /><Input label="GitHub / portfolio" value={resume.personal?.github || resume.personal?.portfolio || ''} onChange={(event) => updatePersonal('github', event.target.value)} /><label className="profile-field">Professional summary<textarea rows="5" value={resume.summary || ''} onChange={(event) => update('summary', event.target.value)} /></label><label className="profile-field">Skills<input value={(resume.skills || []).join(', ')} onChange={(event) => update('skills', event.target.value.split(',').map((item) => item.trim()).filter(Boolean))} placeholder="React, Node.js, MongoDB" /></label><label className="profile-field">Education<textarea rows="4" value={itemsToText(resume.education)} onChange={(event) => update('education', textToItems(event.target.value))} /></label><label className="profile-field">Experience<textarea rows="5" value={itemsToText(resume.experience)} onChange={(event) => update('experience', textToItems(event.target.value))} /></label><label className="profile-field">Projects<textarea rows="5" value={itemsToText(resume.projects)} onChange={(event) => update('projects', textToItems(event.target.value))} /></label><label className="profile-field">Certifications and achievements<textarea rows="4" value={[...itemsToText(resume.certifications), ...itemsToText(resume.achievements)].join('\n')} onChange={(event) => update('certifications', textToItems(event.target.value))} /></label><Button type="submit" variant="nav" loading={saving}><Save size={16} /> Save resume</Button></form>
      <div className="resume-preview-column"><section className="resume-preview"><div className="resume-paper"><span className="resume-kicker">{resume.template || 'ATS MODERN'}</span><h2>{resume.personal?.name || 'Your Name'}</h2><h3>{resume.title || 'Professional Resume'}</h3><p className="resume-contact">{[resume.personal?.email, resume.personal?.phone, resume.personal?.location, resume.personal?.linkedin].filter(Boolean).join(' · ')}</p><ResumeSection title="Summary" value={resume.summary} fallback="Add a concise summary grounded in your profile." /><ResumeSection title="Skills" value={(resume.skills || []).join(' · ')} fallback="Add verified skills." /><ResumeSection title="Education" value={itemsToText(resume.education)} fallback="Add education details." /><ResumeSection title="Experience" value={itemsToText(resume.experience)} fallback="Add experience." /><ResumeSection title="Projects" value={itemsToText(resume.projects)} fallback="Add projects and evidence." /><ResumeSection title="Certifications & achievements" value={[...itemsToText(resume.certifications), ...itemsToText(resume.achievements)].join(' · ')} fallback="Add verified credentials." /></div></section><section className="resume-ai-panel"><div><span className="section-label">AI REVIEW</span><h2>Fact-grounded analysis</h2></div><Button variant="outline" onClick={analyze} loading={saving}><Sparkles size={15} /> Analyze resume</Button>{analysis && <><strong>{analysis.score}% content and alignment signal</strong><p>{(analysis.warnings || []).join(' ') || 'No immediate warnings found.'}</p>{analysis.missingSkills?.length > 0 && <p>Missing or under-emphasized: {analysis.missingSkills.join(', ')}</p>}</>}<label className="profile-field">Ask the Resume Assistant<textarea rows="3" value={assistantText} onChange={(event) => setAssistantText(event.target.value)} placeholder="How can I improve my project section?" /></label><Button variant="outline" onClick={askAssistant} loading={saving}><Sparkles size={15} /> Ask AI</Button>{assistantResult && <div className="ai-suggestion-card"><strong>AI suggestion</strong><p>{assistantResult.answer || assistantResult.suggestion}</p><small>{(assistantResult.why || assistantResult.warnings || []).join(' ')}</small></div>}</section></div>
    </div>
  </div>
}
