import React, { useState } from 'react'
import { Sparkles, Lightbulb } from 'lucide-react'
import { Button, Alert, Input } from '../../../components/common'
import { careerAgentAPI } from '../../../services/careerAgentAPI'

const DIFFICULTY_COLORS = { Beginner: '#2da96d', Intermediate: '#ec7c45', Advanced: '#e05261' }

export const ProjectRecommender = () => {
  const [targetRole, setTargetRole] = useState('')
  const [projects, setProjects] = useState([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  const recommend = async () => {
    if (!targetRole.trim()) return
    setLoading(true)
    setError('')
    try {
      const res = await careerAgentAPI.recommendProjects(targetRole)
      if (res?.success) setProjects(res.data.projects || [])
      else setError('Could not generate project recommendations.')
    } catch (err) {
      setError(err?.message || 'Project recommendation unavailable.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="career-section">
      <div className="career-section-header">
        <span className="section-label">AI PROJECT RECOMMENDER</span>
        <h2>Build projects that get you hired</h2>
        <p className="career-muted">Based on your target role, missing skills, and what internship recruiters actually look for.</p>
      </div>

      <div className="career-role-input">
        <Input
          label="Target Role"
          value={targetRole}
          onChange={(e) => setTargetRole(e.target.value)}
          placeholder="e.g. AI/ML Engineer, Full Stack Developer"
        />
        <Button variant="nav" onClick={recommend} loading={loading} disabled={!targetRole.trim()}>
          <Sparkles size={15} /> Get Project Ideas
        </Button>
      </div>

      {error && <Alert type="error" message={error} />}

      <div className="project-recommendations-grid">
        {projects.map((project, i) => (
          <div key={i} className="project-rec-card">
            <div className="project-rec-header">
              <Lightbulb size={20} color="#ec7c45" />
              <div>
                <h3>{project.name}</h3>
                <span className="difficulty-badge" style={{ color: DIFFICULTY_COLORS[project.difficulty] || '#64717d' }}>
                  {project.difficulty}
                </span>
                <span className="career-muted"> · {project.duration}</span>
              </div>
            </div>
            <p className="project-problem"><strong>Problem:</strong> {project.problem}</p>
            <div className="project-tech-stack">
              {(project.tech || []).map((t) => <span key={t} className="skill-tag">{t}</span>)}
            </div>
            <div className="project-value-row">
              <div><span className="section-label">SKILLS GAINED</span><p>{(project.skillsGained || []).join(', ')}</p></div>
            </div>
            {project.gapsAddressed?.length > 0 && (
              <div className="project-gaps-addressed">
                <span className="section-label">FILLS YOUR GAPS</span>
                {project.gapsAddressed.map((g) => <span key={g} className="skill-tag strong">↑ {g}</span>)}
              </div>
            )}
            {project.aiImplementation && (
              <div className="project-ai-impl">
                <span className="section-label">AI/ML IMPLEMENTATION IDEA</span>
                <p>{project.aiImplementation}</p>
              </div>
            )}
            <div className="project-resume-value">
              <span className="section-label">RESUME VALUE</span>
              <p>{project.resumeValue}</p>
              <span className="section-label">GITHUB TIP</span>
              <p>{project.githubValue}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}
