import React, { useState } from 'react'
import { Sparkles, FileText, ArrowUpRight, AlertCircle } from 'lucide-react'
import { Button, Alert, Input } from '../../../components/common'
import { careerAgentAPI } from '../../../services/careerAgentAPI'

const ROLES = ['AI/ML Engineer', 'Data Scientist', 'Full Stack Developer', 'Backend Developer', 'Frontend Developer', 'Data Analyst', 'DevOps Engineer', 'Cybersecurity Analyst']

export const ATSResumeGenerator = () => {
  const [targetRole, setTargetRole] = useState('')
  const [resume, setResume] = useState(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  const generate = async () => {
    if (!targetRole.trim()) return
    setLoading(true)
    setError('')
    setResume(null)
    try {
      const res = await careerAgentAPI.generateATSResume(targetRole)
      if (res?.success) setResume(res.data.resume)
      else setError('Resume generation failed. Please complete your profile first.')
    } catch (err) {
      setError(err?.message || 'Resume generation unavailable.')
    } finally {
      setLoading(false)
    }
  }

  const goToEditor = () => window.location.href = '/resume'

  return (
    <div className="career-section">
      <div className="career-section-header">
        <span className="section-label">ATS RESUME GENERATOR</span>
        <h2>Generate a targeted, ATS-friendly resume</h2>
        <p className="career-muted">
          Your resume is built exclusively from verified profile data.
          The AI structures and emphasizes content for your target role — it never fabricates experience, metrics, or skills.
        </p>
      </div>

      <div className="career-role-input">
        <label className="career-label">Target Role</label>
        <div className="role-chips">
          {ROLES.map((r) => (
            <button key={r} className={`role-chip ${targetRole === r ? 'active' : ''}`} onClick={() => setTargetRole(r)}>{r}</button>
          ))}
        </div>
        <Input label="Or type a custom role" value={targetRole} onChange={(e) => setTargetRole(e.target.value)} placeholder="e.g. Machine Learning Engineer" />
        <Button variant="nav" onClick={generate} loading={loading} disabled={!targetRole.trim()}>
          <Sparkles size={15} /> Generate ATS Resume
        </Button>
      </div>

      {error && <Alert type="error" message={error} />}

      {resume && (
        <div className="ats-resume-result">
          <div className="ats-resume-notice">
            <AlertCircle size={16} />
            <span>Review every section before submitting. AI generation uses only your profile data — verify accuracy.</span>
          </div>

          {/* Resume preview */}
          <div className="ats-resume-paper">
            <div className="ats-resume-header">
              <h2>{resume.personal?.name || 'Your Name'}</h2>
              <p className="ats-contact">
                {[resume.personal?.email, resume.personal?.phone, resume.personal?.location, resume.personal?.linkedin, resume.personal?.github]
                  .filter(Boolean).join(' · ')}
              </p>
            </div>

            {resume.summary && (
              <div className="ats-section">
                <h3>Professional Summary</h3>
                <p>{resume.summary}</p>
              </div>
            )}

            {resume.skills?.length > 0 && (
              <div className="ats-section">
                <h3>Technical Skills</h3>
                <p>{resume.skills.join(' · ')}</p>
              </div>
            )}

            {resume.education?.length > 0 && (
              <div className="ats-section">
                <h3>Education</h3>
                {resume.education.map((e, i) => <p key={i}>{e.description || JSON.stringify(e)}</p>)}
              </div>
            )}

            {resume.experience?.length > 0 && (
              <div className="ats-section">
                <h3>Experience</h3>
                {resume.experience.map((e, i) => <p key={i}>{e.description || JSON.stringify(e)}</p>)}
              </div>
            )}

            {resume.projects?.length > 0 && (
              <div className="ats-section">
                <h3>Projects</h3>
                {resume.projects.map((p, i) => <p key={i}>{p.description || JSON.stringify(p)}</p>)}
              </div>
            )}

            {resume.certifications?.length > 0 && (
              <div className="ats-section">
                <h3>Certifications</h3>
                {resume.certifications.map((c, i) => <p key={i}>{c.description || JSON.stringify(c)}</p>)}
              </div>
            )}

            {resume.achievements?.length > 0 && (
              <div className="ats-section">
                <h3>Achievements</h3>
                {resume.achievements.map((a, i) => <p key={i}>{a.description || JSON.stringify(a)}</p>)}
              </div>
            )}
          </div>

          <div className="ats-resume-actions">
            <Button variant="nav" onClick={goToEditor}>
              <FileText size={15} /> Open in Resume Editor <ArrowUpRight size={14} />
            </Button>
            <Button variant="outline" onClick={() => window.print()}>
              Export PDF
            </Button>
          </div>
        </div>
      )}
    </div>
  )
}
