import React, { createContext, useContext, useState, useEffect } from 'react'
import { authAPI } from '../services/api'

const AuthContext = createContext()

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  // Initialize auth state from localStorage
  useEffect(() => {
    const accessToken = localStorage.getItem('accessToken')
    const userData = localStorage.getItem('user')

    if (accessToken && userData) {
      try {
        setUser(JSON.parse(userData))
      } catch (err) {
        console.error('Failed to parse user data:', err)
        localStorage.removeItem('accessToken')
        localStorage.removeItem('user')
      }
    }

    setLoading(false)
  }, [])

  const requestLoginOTP = async (email) => {
    try {
      setError(null)
      const response = await authAPI.requestLoginOTP(email)
      return response
    } catch (err) {
      setError(err.message || 'Registration failed')
      throw err
    }
  }

  const loginWithPassword = async (data) => {
    try {
      setError(null)
      const response = await authAPI.loginWithPassword(data)
      if (response?.data?.tokens?.accessToken) {
        localStorage.setItem('accessToken', response.data.tokens.accessToken)
        localStorage.setItem('refreshToken', response.data.tokens.refreshToken)
        setUser(response.data.user)
        localStorage.setItem('user', JSON.stringify(response.data.user))
      }
      return response
    } catch (err) {
      setError(err.message || 'Login failed')
      throw err
    }
  }

  const register = async (data) => {
    try {
      setError(null)
      return await authAPI.register(data)
    } catch (err) {
      setError(err.message || 'Registration failed')
      throw err
    }
  }

  const verifyOTP = async (email, otp) => {
    try {
      setError(null)
      const response = await authAPI.verifyOTP(email, otp)

      if (response?.data?.tokens?.accessToken) {
        localStorage.setItem('accessToken', response.data.tokens.accessToken)
        if (response.data.tokens.refreshToken) {
          localStorage.setItem('refreshToken', response.data.tokens.refreshToken)
        }
        setUser(response.data.user)
        localStorage.setItem('user', JSON.stringify(response.data.user))
      }

      return response
    } catch (err) {
      setError(err.message || 'OTP verification failed')
      throw err
    }
  }

  const verifyRegistrationOTP = async (email, otp) => {
    try {
      setError(null)
      const response = await authAPI.verifyRegistrationOTP(email, otp)
      if (response?.data?.tokens?.accessToken) {
        localStorage.setItem('accessToken', response.data.tokens.accessToken)
        localStorage.setItem('refreshToken', response.data.tokens.refreshToken)
        setUser(response.data.user)
        localStorage.setItem('user', JSON.stringify(response.data.user))
      }
      return response
    } catch (err) {
      setError(err.message || 'Registration verification failed')
      throw err
    }
  }

  const logout = async () => {
    try {
      await authAPI.logout()
    } catch (err) {
      console.error('Logout error:', err)
    } finally {
      setUser(null)
      localStorage.removeItem('accessToken')
      localStorage.removeItem('refreshToken')
      localStorage.removeItem('user')
    }
  }

  const refreshAccessToken = async () => {
    try {
      const refreshToken = localStorage.getItem('refreshToken')
      if (!refreshToken) return false

      const response = await authAPI.refreshToken(refreshToken)

      if (response?.data?.accessToken) {
        localStorage.setItem('accessToken', response.data.accessToken)
        return true
      }

      return false
    } catch (err) {
      console.error('Token refresh failed:', err)
      return false
    }
  }

  const value = {
    user,
    loading,
    error,
    isAuthenticated: !!user,
    requestLoginOTP,
    loginWithPassword,
    register,
    verifyOTP,
    verifyRegistrationOTP,
    logout,
    refreshAccessToken,
  }

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

export const useAuth = () => {
  const context = useContext(AuthContext)
  if (!context) {
    throw new Error('useAuth must be used within AuthProvider')
  }
  return context
}
