import React, { useState } from 'react'
import { ArrowRight, Building2, Eye, EyeOff, GraduationCap, Landmark, LockKeyhole, Mail, Users, AlertCircle } from 'lucide-react'
import { Link, useNavigate } from 'react-router-dom'
import { Button, Input, Card, Alert } from './common'
import { useAuth } from '../context/AuthContext'
import { validateEmail, getErrorMessage } from '../utils/helpers'
import { ROUTES } from '../utils/constants'

const roles = [
  ['student', 'Student', GraduationCap],
  ['industry', 'Industry', Building2],
  ['academician', 'Academician', Users],
  ['institution', 'Institution', Landmark],
]

export const LoginForm = () => {
  const [form, setForm] = useState({ email: '', password: '', role: 'student' })
  const [showPassword, setShowPassword] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const { loginWithPassword } = useAuth()
  const navigate = useNavigate()

  const change = (field) => (event) => {
    setError('')
    setForm((current) => ({ ...current, [field]: event.target.value }))
  }

  const submit = async (event) => {
    event.preventDefault()
    setError('')

    if (!form.email || !validateEmail(form.email)) {
      setError('Please enter a valid email address.')
      return
    }

    if (!form.password) {
      setError('Please enter your password.')
      return
    }

    setLoading(true)
    try {
      await loginWithPassword(form)
      navigate(ROUTES.DASHBOARD)
    } catch (err) {
      console.warn('[LoginForm] Authentication failed:', err)
      const msg = getErrorMessage(err)
      setError(msg || 'Invalid email or password. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <Card className="auth-card max-w-md mx-auto">
      <div className="auth-card-header">
        <div className="auth-card-icon">
          <LockKeyhole size={19} />
        </div>
        <div>
          <span className="section-label">SECURE ACCESS</span>
          <h2>Welcome to AICP</h2>
        </div>
      </div>
      <p className="auth-card-subtitle">Sign in to access your role-based workspace.</p>

      {error && (
        <div style={{ marginBottom: 16 }}>
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 10,
              padding: '12px 14px',
              borderRadius: '8px',
              background: '#fef2f2',
              border: '1px solid #fecaca',
              color: '#991b1b',
              fontSize: '13px',
              fontWeight: 500,
            }}
          >
            <AlertCircle size={18} color="#dc2626" style={{ flexShrink: 0 }} />
            <span style={{ flex: 1 }}>{error}</span>
            <button
              type="button"
              onClick={() => setError('')}
              style={{
                background: 'none',
                border: 'none',
                color: '#991b1b',
                cursor: 'pointer',
                fontWeight: 700,
                fontSize: '16px',
                padding: '0 4px',
              }}
            >
              ×
            </button>
          </div>
        </div>
      )}

      <form onSubmit={submit} className="space-y-4">
        <label className="auth-role-label">
          I am signing in as
          <div className="auth-role-grid">
            {roles.map(([value, label, Icon]) => (
              <label className={form.role === value ? 'auth-role selected' : 'auth-role'} key={value}>
                <input
                  type="radio"
                  name="login-role"
                  value={value}
                  checked={form.role === value}
                  onChange={change('role')}
                />
                <Icon size={17} />
                <strong>{label}</strong>
              </label>
            ))}
          </div>
        </label>

        <Input
          label="Email address"
          type="email"
          value={form.email}
          onChange={change('email')}
          placeholder="Enter your email"
          required
          disabled={loading}
        />

        <div className="password-field-group">
          <div className="password-label-row">
            <label htmlFor="login-password">Password *</label>
            <Link to="/register">Need an account?</Link>
          </div>
          <div className="password-control">
            <input
              id="login-password"
              type={showPassword ? 'text' : 'password'}
              value={form.password}
              onChange={change('password')}
              placeholder="Enter your password"
              required
              disabled={loading}
            />
            <button
              type="button"
              onClick={() => setShowPassword((value) => !value)}
              aria-label={showPassword ? 'Hide password' : 'Show password'}
            >
              {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
            </button>
          </div>
        </div>

        <label className="auth-remember">
          <input type="checkbox" /> Remember me
        </label>

        <Button type="submit" variant="primary" size="lg" loading={loading} className="w-full">
          Sign in <ArrowRight size={16} />
        </Button>
      </form>

      <div className="auth-card-foot">
        <span>
          <Mail size={14} /> Email and password protected
        </span>
        <Link to="/register">
          Create account <ArrowRight size={14} />
        </Link>
      </div>
    </Card>
  )
}
