import React, { useState } from 'react'
import { Sparkles, CheckCircle2, AlertCircle } from 'lucide-react'
import { Button, Alert } from '../../../components/common'
import { careerAgentAPI } from '../../../services/careerAgentAPI'

export const JobDescAnalyzer = () => {
  const [jd, setJd] = useState('')
  const [result, setResult] = useState(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  const analyze = async () => {
    if (!jd.trim()) return
    setLoading(true)
    setError('')
    setResult(null)
    try {
      const res = await careerAgentAPI.analyzeJobDescription(jd)
      if (res?.success) setResult(res.data)
      else setError('Analysis failed. Please try again.')
    } catch (err) {
      setError(err?.message || 'Job description analysis unavailable.')
    } finally {
      setLoading(false)
    }
  }

  const scoreColor = (score) => score >= 70 ? '#2da96d' : score >= 40 ? '#ec7c45' : '#e05261'

  return (
    <div className="career-section">
      <div className="career-section-header">
        <span className="section-label">JOB DESCRIPTION ANALYZER</span>
        <h2>See how well you match any job or internship</h2>
        <p className="career-muted">Paste a job description below. The AI will extract required skills and compare them against your profile.</p>
      </div>

      <div className="jd-input-area">
        <label className="career-label">Job Description</label>
        <textarea
          className="jd-textarea"
          value={jd}
          onChange={(e) => setJd(e.target.value)}
          placeholder="Paste the full job description here…"
          rows={10}
        />
        <Button variant="nav" onClick={analyze} loading={loading} disabled={!jd.trim()}>
          <Sparkles size={15} /> Analyze Match
        </Button>
      </div>

      {error && <Alert type="error" message={error} />}

      {result && (
        <div className="jd-result">
          {/* Match score */}
          <div className="jd-score-hero" style={{ borderColor: scoreColor(result.matchScore) }}>
            <strong style={{ color: scoreColor(result.matchScore) }}>{result.matchScore}%</strong>
            <span>JOB MATCH SCORE</span>
            <p>Based on {result.jdSkills?.length || 0} skills identified in the job description.</p>
          </div>

          <div className="jd-skills-grid">
            {/* Matched */}
            <div className="jd-skills-col">
              <span className="section-label">MATCHING SKILLS</span>
              {result.matchedSkills?.length > 0
                ? result.matchedSkills.map((s) => <div key={s} className="skill-row"><CheckCircle2 size={15} color="#2da96d" /> {s}</div>)
                : <p className="career-muted">No matching skills detected. Add more skills to your profile.</p>
              }
            </div>

            {/* Missing */}
            <div className="jd-skills-col">
              <span className="section-label">MISSING SKILLS</span>
              {result.missingSkills?.length > 0
                ? result.missingSkills.map((s) => <div key={s} className="skill-row missing"><AlertCircle size={15} color="#e05261" /> {s}</div>)
                : <p className="career-muted">No critical missing skills detected. Great match!</p>
              }
            </div>
          </div>

          {/* Resume improvements */}
          {result.resumeImprovements?.length > 0 && (
            <div className="jd-improvements">
              <span className="section-label">RESUME IMPROVEMENTS</span>
              <p className="career-muted">Only add skills you actually have. Do not fabricate qualifications.</p>
              <ul>
                {result.resumeImprovements.map((item, i) => (
                  <li key={i}>{item}</li>
                ))}
              </ul>
            </div>
          )}
        </div>
      )}
    </div>
  )
}
