import React, { useState, useRef } from 'react'
import { Volume2, VolumeX, Play, Pause, Sparkles, ExternalLink } from 'lucide-react'

export const HeroCompanionShowcase = () => {
  const [isMuted, setIsMuted] = useState(true)
  const [isPlaying, setIsPlaying] = useState(true)
  const videoRef = useRef(null)

  const toggleSound = (e) => {
    e.stopPropagation()
    if (!videoRef.current) return
    const nextMuted = !isMuted
    videoRef.current.muted = nextMuted
    setIsMuted(nextMuted)
  }

  const togglePlay = () => {
    if (!videoRef.current) return
    if (isPlaying) {
      videoRef.current.pause()
      setIsPlaying(false)
    } else {
      videoRef.current.play()
      setIsPlaying(true)
    }
  }

  return (
    <div className="hero-companion-showcase tilt-card-3d" onClick={togglePlay}>
      {/* Ambient Glow Aura */}
      <div className="companion-glow-aura" />

      {/* Video Container */}
      <div className="companion-video-wrapper">
        <video
          ref={videoRef}
          src="/robot-companion.mp4"
          poster="/robot-companion-poster.jpg"
          autoPlay
          loop
          muted={isMuted}
          playsInline
          className="companion-video"
          aria-label="Interactive 3D Robot Companion"
        />

        {/* Hologram Glass Sheen Overlay */}
        <div className="companion-hologram-sheen" />

        {/* Top Header Floating Badge */}
        <div className="companion-top-badge">
          <span className="companion-live-dot" />
          <Sparkles size={11} className="text-pink-400" />
          <span>AICP 3D Companion</span>
        </div>

        {/* Bottom Interactive Controls Bar */}
        <div className="companion-bottom-bar" onClick={(e) => e.stopPropagation()}>
          <a
            href="https://pin.it/3MPX3Wxzo"
            target="_blank"
            rel="noopener noreferrer"
            className="companion-source-pill"
            title="View reference on Pinterest"
            onClick={(e) => e.stopPropagation()}
          >
            <Sparkles size={10} className="text-pink-400" />
            <span>Interactive 3D Bot</span>
            <ExternalLink size={10} className="opacity-80" />
          </a>

          <div className="companion-action-btns">
            <button
              type="button"
              className="companion-icon-btn"
              onClick={toggleSound}
              title={isMuted ? 'Unmute video audio' : 'Mute video audio'}
              aria-label={isMuted ? 'Unmute' : 'Mute'}
            >
              {isMuted ? <VolumeX size={13} /> : <Volume2 size={13} className="text-pink-400" />}
            </button>

            <button
              type="button"
              className="companion-icon-btn"
              onClick={(e) => {
                e.stopPropagation()
                togglePlay()
              }}
              title={isPlaying ? 'Pause video' : 'Play video'}
              aria-label={isPlaying ? 'Pause' : 'Play'}
            >
              {isPlaying ? <Pause size={13} /> : <Play size={13} className="text-pink-400" />}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

export default HeroCompanionShowcase

