import React, { useEffect, useState } from 'react'
import { ArrowLeft, CheckCircle2, ChevronRight, Clock3, RotateCcw, Target } from 'lucide-react'
import { Button } from './common'
import { assessmentAPI } from '../services/api'

const demoAssessment = {
  _id: 'demo-assessment', title: 'Core Data & AI Readiness', description: 'A short assessment to establish your starting skill signal.', duration: 10, passingScore: 60,
  questions: [
    { question: 'Which tool is commonly used to manipulate tabular data in Python?', options: ['React', 'Pandas', 'Docker', 'Figma'], correctAnswer: 1 },
    { question: 'What does a classification model predict?', options: ['A category or label', 'Only images', 'Database size', 'A CSS color'], correctAnswer: 0 },
    { question: 'Which SQL clause filters grouped results?', options: ['ORDER BY', 'WHERE', 'HAVING', 'JOIN'], correctAnswer: 2 },
  ],
}

export const AssessmentCenter = () => {
  const [assessments, setAssessments] = useState([])
  const [assessment, setAssessment] = useState(null)
  const [answers, setAnswers] = useState({})
  const [result, setResult] = useState(null)
  const [attemptId, setAttemptId] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  useEffect(() => {
    assessmentAPI.getAssessments({ limit: 10 }).then((response) => {
      const items = response?.data?.items || []
      setAssessments(items.length ? items : [demoAssessment])
    }).catch(() => { setAssessments([demoAssessment]); setError('Live assessments unavailable. Try the included demo assessment.') }).finally(() => setLoading(false))
  }, [])

  const begin = async (item) => {
    setError(''); setResult(null); setAnswers({}); setAssessment(item)
    if (item._id === 'demo-assessment') return
    try { const response = await assessmentAPI.startAssessment(item._id); setAttemptId(response?.data?.attemptId) } catch (err) { setError(err.message || 'Could not start this assessment.') }
  }

  const submit = async () => {
    const unanswered = assessment.questions.some((_, index) => answers[index] === undefined)
    if (unanswered) { setError('Answer every question before submitting.'); return }
    setLoading(true)
    try {
      if (assessment._id === 'demo-assessment') {
        const correct = assessment.questions.reduce((total, question, index) => total + (Number(answers[index]) === question.correctAnswer ? 1 : 0), 0)
        setResult({ score: Math.round((correct / assessment.questions.length) * 100), correctAnswers: correct, totalQuestions: assessment.questions.length, passed: correct / assessment.questions.length >= 0.6 })
      } else {
        await Promise.all(Object.entries(answers).map(([questionIndex, selectedOption]) => assessmentAPI.submitAnswer(assessment._id, { attemptId, questionIndex, selectedOption })))
        const response = await assessmentAPI.completeAssessment(attemptId)
        setResult(response?.data)
      }
    } catch (err) { setError(err.message || 'Could not submit the assessment.') } finally { setLoading(false) }
  }

  if (loading && !assessments.length) return <div className="workspace-empty">Loading assessments...</div>
  if (!assessment) return <div className="assessment-center"><div className="assessment-intro"><Target size={22} /><div><span className="section-label">SKILL SIGNAL CHECK</span><h2>Choose an assessment to begin</h2><p>Answer a few focused questions and turn your knowledge into evidence for better matches.</p></div></div>{error && <p className="workspace-error">{error}</p>}<div className="assessment-cards">{assessments.map((item) => <article key={item._id} className="assessment-card"><div><span className="assessment-type">{item.type || 'Skill test'}</span><h3>{item.title}</h3><p>{item.description || 'Measure your current capability and discover your next learning move.'}</p></div><div className="assessment-meta"><span><Clock3 size={14} /> {item.duration || 30} min</span><span>{item.questions?.length || 0} questions</span></div><Button variant="nav" onClick={() => begin(item)}>Start assessment <ChevronRight size={16} /></Button></article>)}</div></div>

  if (result) return <div className="assessment-result"><div className="result-icon"><CheckCircle2 size={34} /></div><span className="section-label">ASSESSMENT COMPLETE</span><h2>{result.passed ? 'Strong signal. Keep building.' : 'Good start. Your next step is clear.'}</h2><strong>{result.score}%</strong><p>{result.correctAnswers} of {result.totalQuestions} answers correct. {result.passed ? 'Your profile is ready for stronger opportunity matches.' : 'Use the skill gaps to guide your next learning sprint.'}</p><Button variant="outline" onClick={() => setAssessment(null)}><RotateCcw size={16} /> Take another assessment</Button></div>

  return <div className="assessment-runner"><button className="assessment-back" onClick={() => setAssessment(null)}><ArrowLeft size={16} /> All assessments</button><div className="runner-heading"><div><span className="section-label">QUESTIONNAIRE</span><h2>{assessment.title}</h2></div><span>{Object.keys(answers).length}/{assessment.questions.length} answered</span></div>{error && <p className="workspace-error">{error}</p>}<div className="question-list">{assessment.questions.map((question, index) => <fieldset className="question-card" key={question._id || index}><legend>{index + 1}. {question.question}</legend><div className="option-grid">{question.options.map((option, optionIndex) => <label className={Number(answers[index]) === optionIndex ? 'option selected' : 'option'} key={option}><input type="radio" name={`question-${index}`} checked={Number(answers[index]) === optionIndex} onChange={() => setAnswers((current) => ({ ...current, [index]: optionIndex }))} />{option}</label>)}</div></fieldset>)}</div><Button variant="nav" size="lg" onClick={submit} loading={loading}>Submit assessment <CheckCircle2 size={17} /></Button></div>
}
