import React, { useEffect, useState } from 'react'
import { Link, useLocation } from 'react-router-dom'
import { ArrowLeft, ArrowUpRight, BarChart3, Bell, BookOpen, BrainCircuit, Briefcase, CheckCircle2, FileText, Network, Search, Target } from 'lucide-react'
import { Button } from '../components/common'
import { AssessmentCenter } from '../components/AssessmentCenter'
import { ProfileEditor } from '../components/ProfileEditor'
import { ApplicationTracker } from '../components/ApplicationTracker'
import { ROUTES } from '../utils/constants'
import { analyticsAPI, applicationAPI, assessmentAPI, collaborationAPI, documentAPI, internshipAPI, learningAPI, notificationAPI, opportunitiesAPI, portfolioAPI, profileAPI, skillsAPI } from '../services/api'

const views = {
  '/learning': ['Learning studio', 'Build the focused skills your next opportunity asks for.', BookOpen, ['Browse learning programs', 'Track your progress', 'Earn verified certificates']],
  '/collaborations': ['Collaboration hub', 'Find the people and projects that make good work possible.', Network, ['Research partnerships', 'Project requests', 'Mentorship connections']],
  '/profile': ['Your profile signal', 'Keep your story current so the right opportunities can find you.', FileText, ['Personal details', 'Skills and assessments', 'Portfolio and proof']],
  '/opportunities': ['Opportunity radar', 'Explore roles, internships, and projects matched to your momentum.', Search, ['Recommended for you', 'Recently published', 'Saved opportunities']],
  '/applications': ['Application tracker', 'See every opportunity move from applied to outcome.', Briefcase, ['In review', 'Shortlisted', 'Interview schedule']],
  '/analytics': ['Analytics room', 'Read the signals behind progress, readiness, and outcomes.', BarChart3, ['Student readiness', 'Skill coverage', 'Placement outcomes']],
  '/assessments': ['Assessment center', 'Measure what you know and turn results into stronger evidence.', BrainCircuit, ['Published assessments', 'Your attempts', 'Recommended next test']],
  '/internships': ['Internship tracker', 'Follow the journey from selection to completion.', Briefcase, ['Planned internships', 'Ongoing experiences', 'Completed experiences']],
  '/notifications': ['Notifications', 'Keep up with applications, deadlines, and collaboration activity.', Bell, ['Unread updates', 'Application activity', 'System updates']],
  '/skills': ['Skill profile', 'Keep your evidence current so recommendations reflect your real capability.', BrainCircuit, ['Verified skills', 'Assessment evidence', 'Skills to develop']],
  '/documents': ['My documents', 'Manage the resumes and supporting documents connected to your profile.', FileText, ['Resumes', 'Certificates', 'Project documents']],
}

const demoRecords = {
  '/opportunities': [
    { title: 'AI Research Intern', company: 'Mitra Health Labs', type: 'Internship', location: 'Bengaluru · Hybrid', match: 94, skills: 'Python, Machine Learning, SQL' },
    { title: 'Product Data Analyst', company: 'Sattva Systems', type: 'Full-time', location: 'Remote · India', match: 86, skills: 'SQL, Tableau, Statistics' },
    { title: 'Ayurveda Tech Fellowship', company: 'Prana Digital Health', type: 'Fellowship', location: 'Pune · On-site', match: 78, skills: 'Research, Communication, Python' },
  ],
  '/applications': [
    { title: 'AI Research Intern', company: 'Mitra Health Labs', status: 'Shortlisted', date: 'Updated today' },
    { title: 'Data Science Apprentice', company: 'Nila Analytics', status: 'Interview', date: 'Interview · 12 Sep' },
    { title: 'Campus Innovation Challenge', company: 'AICP Network', status: 'Applied', date: 'Applied 28 Aug' },
  ],
  '/skills': [
    { title: 'Python', value: '82%', note: 'Strong signal from assessment and projects' },
    { title: 'Machine Learning', value: '64%', note: 'Build one deployed project to improve this signal' },
    { title: 'Data Storytelling', value: '48%', note: 'Most requested gap for your target roles' },
  ],
}

const toDisplayText = (value, fallback = '') => {
  if (value === null || value === undefined || value === '') return fallback
  if (Array.isArray(value)) return value.map((item) => toDisplayText(item)).filter(Boolean).join(', ')
  if (typeof value === 'object') return toDisplayText(value.name || value.title || value.label || value.category, fallback)
  return String(value)
}

export const WorkspacePage = () => {
  const { pathname } = useLocation()
  const [title, copy, Icon, items] = views[pathname] || views['/profile']
  const [records, setRecords] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  useEffect(() => {
      const loaders = {
      '/learning': () => learningAPI.getPrograms({ limit: 10 }),
      '/opportunities': () => opportunitiesAPI.getOpportunities({ limit: 10 }),
      '/applications': () => applicationAPI.getApplications({ limit: 10 }),
      '/analytics': () => analyticsAPI.getStudent(),
      '/assessments': () => assessmentAPI.getAssessments({ limit: 10 }),
      '/internships': () => internshipAPI.getInternships(),
      '/notifications': () => notificationAPI.getNotifications({ limit: 10 }),
      '/skills': () => skillsAPI.getSkills({ limit: 20 }),
      '/documents': () => documentAPI.getDocuments({ limit: 20 }),
      '/collaborations': () => collaborationAPI.getCollaborations(),
      '/profile': () => profileAPI.getProfile(),
    }
    const loader = loaders[pathname]
    if (!loader) { setLoading(false); return undefined }
    setLoading(true)
    loader().then((response) => {
      const data = response?.data || {}
      const values = data.items ?? data.cards ?? data.skills ?? (data.portfolio ? [data.portfolio] : null) ?? (data.profile ? [data.profile] : null) ?? (data.metrics ? Object.entries(data.metrics).map(([label, value]) => ({ label, value })) : [])
      setRecords(values.length ? values : pathname === '/applications' ? [] : demoRecords[pathname] || [])
    }).catch(() => { setRecords(pathname === '/applications' ? [] : demoRecords[pathname] || []); setError('This workspace could not load its live data.') }).finally(() => setLoading(false))
    return undefined
  }, [pathname])

  const isOpportunities = pathname === '/opportunities'
  const isApplications = pathname === '/applications'
  const isSkills = pathname === '/skills'
  const [applied, setApplied] = useState([])

  if (pathname === '/assessments') return <div className="workspace-page"><Link to={ROUTES.DASHBOARD} className="back-link"><ArrowLeft size={16} /> Back to workspace</Link><AssessmentCenter /></div>
  if (pathname === '/profile') return <div className="workspace-page"><Link to={ROUTES.DASHBOARD} className="back-link"><ArrowLeft size={16} /> Back to workspace</Link><ProfileEditor /></div>
  if (isApplications) return <div className="workspace-page"><Link to={ROUTES.DASHBOARD} className="back-link"><ArrowLeft size={16} /> Back to workspace</Link><div className="workspace-hero"><div className="workspace-icon"><Icon size={28} /></div><span className="section-label">AICP WORKSPACE</span><h1>{title}</h1><p>{copy}</p></div><ApplicationTracker applications={records} loading={loading} error={error} /></div>

  return <div className="workspace-page"><Link to={ROUTES.DASHBOARD} className="back-link"><ArrowLeft size={16} /> Back to workspace</Link><div className="workspace-hero"><div className="workspace-icon"><Icon size={28} /></div><span className="section-label">AICP WORKSPACE</span><h1>{title}</h1><p>{copy}</p><Button variant="nav" onClick={() => window.scrollTo({ top: 480, behavior: 'smooth' })}>Explore this space <ArrowUpRight size={17} /></Button></div>{error && <p className="workspace-error">Live data unavailable. Showing the workspace preview.</p>}<div className="workspace-insight"><div className="insight-icon"><Target size={19} /></div><div><span className="section-label">INTELLIGENCE LAYER</span><strong>{isOpportunities ? 'Ranked by your skill fit' : isApplications ? 'Your application momentum' : isSkills ? 'Close the highest-value gap next' : 'A connected view of your progress'}</strong><p>{isOpportunities ? 'Match scores compare your assessed skills with each opportunity requirement.' : isApplications ? 'Keep your pipeline moving with clear next actions and status visibility.' : isSkills ? 'A focused learning path in Data Storytelling could lift your role readiness by 18%.' : 'Every workspace module turns a signal into a practical next move.'}</p></div></div><div className="workspace-list">{loading ? <div className="workspace-empty">Loading live workspace data...</div> : records.length ? records.map((record, index) => { const label = toDisplayText(record.title || record.name || record.label || record.type, `Workspace record ${index + 1}`); const detail = toDisplayText(record.description || record.note || record.message || record.status || (record.value !== undefined ? record.value : ''), 'Available in your AICP workspace.'); const company = toDisplayText(record.company, detail); const skills = toDisplayText(record.skills || record.date, detail); const status = toDisplayText(record.status, 'Applied'); const alreadyApplied = applied.includes(label); return <article className="workspace-record" key={record._id || `${label}-${index}`}><span className="record-number">0{index + 1}</span><div className="record-main"><div className="record-heading"><div><h2>{label}</h2><p>{company}</p></div>{record.match && <strong className="match-score">{record.match}% fit</strong>}</div><p className="record-detail">{skills}</p>{isSkills && record.value && <div className="skill-meter"><span style={{ width: toDisplayText(record.value) }} /></div>}</div>{isOpportunities ? <button className="record-action" disabled={alreadyApplied} onClick={() => setApplied((current) => [...current, label])}>{alreadyApplied ? <><CheckCircle2 size={17} /> Applied</> : <>Apply <ArrowUpRight size={17} /></>}</button> : isApplications ? <span className="status-pill"><CheckCircle2 size={14} /> {status}</span> : <ArrowUpRight size={18} className="record-arrow" />}</article> }) : items.map((item, index) => <article key={item}><span>0{index + 1}</span><div><h2>{item}</h2><p>No records yet. This module is ready for your first entry.</p></div><ArrowUpRight size={18} /></article>)}</div></div>
}

